SELECT DATE_TRUNC('WEEK', txn_time) AS week_start, DATE_TRUNC('QUARTER', txn_time) AS quarter_start, MIN(txn_time) AS started_at, ROUND(SUM(amount) / NULLIF(COUNT(CASE WHEN txn_type = 'REFUND' THEN 1 END), 0), 2) AS amount_per_refund, COUNT(CASE WHEN merchant = 'Starbucks' THEN 1 END) AS starbucks_count FROM transactions GROUP BY DATE_TRUNC('WEEK', txn_time), DATE_TRUNC('QUARTER', txn_time);
